    # The 5 row separates two panels. Each colored object is a vertical bar;
    # select the color whose bar grows by more cells from top to bottom.
    split = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    upper, lower = grid[:split], grid[split + 1:]
    growth = {}
    for color in (2, 4):
        top_count = sum(cell == color for row in upper for cell in row)
        bottom_count = sum(cell == color for row in lower for cell in row)
        growth[color] = bottom_count - top_count
    color = 2 if growth[2] > growth[4] else 4
    return [[color, color], [color, color]]
