 "content": "def transform(grid):
    # The line color is the one whose vertical bar has the least interruption
    # across the horizontal divider's two panels.
    split = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    top, bottom = grid[:split], grid[split + 1:]
    scores = {}
    for color in (2, 4):
        heights = []
        for panel in (top, bottom):
            maxrun = 0
            for col in range(len(grid[0])):
                run = 0
                for row in panel:
                    if row[col] == color:
                        run += 1
                        maxrun = max(maxrun, run)
                    else:
                        run = 0
            heights.append(maxrun)
        scores[color] = sum(heights)
    color = 2 if scores[2] > scores[4] else 4
    return [[color, color], [color, color]]
